    /**
     * Method to retrieve the Patient via an FindPatientQuery
     * @return 	query	FindPatientQuery
     */
    @SuppressWarnings("unused")
    public Patient find( UUID id ) {
    	LOGGER.info("handling find using " + id.toString() );
    	try {
    		return repository.findById(id).get();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find a Patient - {0}", exc.getMessage() );
    	}
    	return null;
    }
    
    /**
     * Method to retrieve a collection of all Patients
     *
     * @param	query	FindAllPatientQuery 
     * @return 	List<Patient> 
     */
    @SuppressWarnings("unused")
    public List<Patient> findAll( FindAllPatientQuery query ) {
    	LOGGER.info("handling findAll using " + query.toString() );
    	try {
    		return repository.findAll();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find all Patient - {0}", exc.getMessage() );
    	}
    	return null;
    }


